nt-medium">Motif *</label><textarea v-model="form.reason" rows="4" required class="w-full rounded-lg border border-gray-200 px-3 py-2 text-sm dark:border-gray-800 dark:bg-gray-950 dark:text-white"/><FormError v-if="form.errors.reason">{{form.errors.reason}}</FormError></div></div></section><div class="flex justify-end gap-2"><Button :as="Link" href="/administration/leave" size="rg" variant="white-outline">Annuler</Button><Button size="rg" :disabled="form.processing"><Icon name="check"/><span class="ms-2">Enregistrer la demande</span></Button></div></form></div></template>
